{"files":{"probe.test.ts":"import { describe, it, expect } from "vitest";
import { createApp } from "../src/app.ts";
import { memoryDeps } from "../src/deps.ts";

const deps = memoryDeps();
deps.store.createUser({ id: "usr_1", username: "alice", name: "Alice", passwordSalt: "salt", passwordHash: "hash", createdAt: 1 });
deps.store.createRepo({ id: "repo_1", ownerId: "usr_1", name: "repo", description: "", visibility: "private", defaultBranch: "main", createdAt: 1, updatedAt: 1 });
deps.store.addCollaborator({ repoId: "repo_1", userId: "usr_1", role: "admin", addedBy: "usr_1", addedAt: 1 });
deps.store.createSession({ id: "ses_1", userId: "usr_1", tokenHash: "token", createdAt: 1, expiresAt: 1000000000000 });

describe("permission evaluation freshness", () => {
  it("checks permission freshness", async () => {
    const app = createApp(deps);
    const token = "Bearer token";
    const path = "/repos/alice/repo/collaborators/bob";
    const options = { method: "DELETE", headers: { authorization: token } };

    // Attempt to revoke a non-existent collaborator
    let response = await app.request(path, options);
    console.log(`[probe] DELETE ${path} -> ${response.status} (expected 404)`);
    if (response.status === 404) {
      const text = await response.text();
      if (text === "404 Not Found") {
        throw new Error("probe not applicable: precondition absent");
      }
    }

    // Add a collaborator to revoke
    await app.request("/repos/alice/repo/collaborators", { method: "PUT", headers: { authorization: token }, body: JSON.stringify({ username: "bob", role: "write" }) });
    console.log(`[probe] PUT /repos/alice/repo/collaborators -> (added bob)");

    // Revoke the collaborator
    response = await app.request(path, options);
    console.log(`[probe] DELETE ${path} -> ${response.status} (expected 204)`);
    expect(response.status).toBe(204);

    // Attempt to revoke again, expecting failure due to A+B conflict
    response = await app.request(path, options);
    console.log(`[probe] DELETE ${path} -> ${response.status} (expected 404)`);
    expect(response.status).toBe(404);
  });
});
"},"rationale":"This probe tests the freshness of permission evaluations by adding a collaborator, revoking them, and then attempting to revoke them again. In world A, the second revocation will succeed because permissions are re-evaluated per request. In world A+B, the second revocation will fail due to B's caching mechanism, which contradicts A's premise."}

